 async function saveGallery(nextGallery=gallery,nextCover=meta.cover_url){const fallbackCover=nextCover||nextGallery.find(item=>(item?.kind||'').toLowerCase()==='front')?.url||nextGallery[0]?.url||'';if(fallbackCover!==meta.cover_url)setMeta(x=>({...x,cover_url:fallbackCover}));setBusy(true);const {error}=await supabase.rpc('admin_update_merch_gallery',{p_product_id:product.id,p_gallery:nextGallery,p_cover_url:fallbackCover||null});setBusy(false);if(error){setMsg(error.message);return false}setMsg('Gallery saved.');if(onSaved)await onSaved();return true;}
